window.changeLanguage = function(lang) {
  const t = translations[lang];
  if (!t) return;
  
  const mapping = {
    "title": t.title,
    "subtitle": t.subtitle,
    "disclaimer": t.disclaimer,
    "step1": t.step1,
    "step2": t.step2,
    "step3": t.step3,
    "step4": t.step4,
    "step5": t.step5,
    "step6": t.step6,
    "step7": t.step7,
    "step8": t.step8,
    "quickLinks": t.quickLinks,
    "btnTvApk": `<span class="btn-icon">📺</span>${t.btnTvApk}`,
    "btnPhoneApp": `<span class="btn-icon">📱</span>${t.btnPhoneApp}`,
    "btnActivation": `<span class="btn-icon">🔑</span>${t.btnActivation}`,
    "faqTitle": t.faqTitle,
    "faq1_q": t.faq1_q,
    "faq1_a": t.faq1_a,
    "faq2_q": t.faq2_q,
    "faq2_a": t.faq2_a,
    "faq3_q": t.faq3_q,
    "faq3_a": t.faq3_a,
    "faq4_q": t.faq4_q,
    "faq4_a": t.faq4_a,
    "faq5_q": t.faq5_q,
    "faq5_a": t.faq5_a,
    "faq6_q": t.faq6_q,
    "faq6_a": t.faq6_a,
    "faq7_q": t.faq7_q,
    "faq7_a": t.faq7_a,
    "faq8_q": t.faq8_q,
    "faq8_a": t.faq8_a,
    "faq9_q": t.faq9_q,
    "faq9_a": t.faq9_a,
    "faq10_q": t.faq10_q,
    "faq10_a": t.faq10_a,
    "sponsorsTitle": t.sponsorsTitle,
    "sponsorApp": `<strong>${t.sponsorApp}</strong>`,
    "totalViews": t.totalViews
  };

  for (const [key, value] of Object.entries(mapping)) {
    const el = document.querySelector(`[data-i18n="${key}"]`);
    if (el) {
      el.innerHTML = value;
    }
  }
};
